      ["反導數 (2/3)u^(3/2) − 2u^(1/2)，從 1 到 9：(18 − 6) − (2/3 − 2) = 12 + 4/3。", "SUB((2/3)*x^(3/2)-2x^(1/2), 9) - SUB((2/3)*x^(3/2)-2x^(1/2), 1) == 12+4/3"],
      ["乘 1/4：10/3。", "(12+4/3)/4 == ANS"]
